-- 20 September 2026 daily current-affairs desk.
-- Original revision briefs based on primary official releases issued from 16 to 19 September.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
  $$2026-09-20-ngmv-first-keel-laying$$, $$2026-09-20$$,
  $$First Next Generation Missile Vessel enters construction at Cochin Shipyard$$,
  $$The Indian Navy held the keel-laying ceremony for the first Next Generation Missile Vessel (NGMV) at Cochin Shipyard Limited, Kochi, on 18 September. The NGMV construction contract with the shipyard was concluded in March 2023.$$,
  $$Keel laying is a shipbuilding milestone, not commissioning or induction into naval service. The brief connects defence modernisation with indigenous manufacturing and India’s maritime role in the Indian Ocean Region.$$,
  $$The Ministry of Defence says the vessels are planned to carry modern weapons and sensors. It also notes that the project’s major role-defining equipment is to be developed and manufactured domestically, linking the programme to Aatmanirbhar Bharat, Make in India and Make for the World.$$,
  $$Keel Laying of First Next Generation Missile Vessel for Indian Navy at Cochin Shipyard Limited, Kochi$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2312326&lang=2&reg=48$$,
  $$Ministry of Defence / Press Information Bureau$$, $$2026-09-19$$,
  $$["The first NGMV's keel was laid at Cochin Shipyard Limited in Kochi on 18 September 2026.","The NGMV construction contract with CSL was concluded in March 2023.","Keel laying marks a construction stage; it is distinct from launch, sea trials, commissioning and induction.","The project emphasises domestic development and manufacture of major role-defining equipment."]$$::jsonb,
  $$[{"question":"Where was the first NGMV keel laid?","answer":"Cochin Shipyard Limited, Kochi."},{"question":"Does keel laying mean the vessel has joined the Navy?","answer":"No. It is an early ship-construction milestone."}]$$::jsonb,
  $${"title":"From warship contract to fleet capability","steps":["The Navy contracts an Indian shipyard.","Keel laying begins physical construction of the first vessel.","Weapons, sensors and indigenous equipment are integrated during build.","Trials and commissioning must follow before operational service."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-20-nlmc-asset-monetisation$$, $$2026-09-20$$,
  $$NLMC recommends over ₹5,000 crore of surplus public assets for monetisation$$,
  $$National Land Monetization Corporation Limited's board reviewed the asset-monetisation programme and recommended proposals involving surplus land and buildings valued at over ₹5,000 crore. The board also approved its FY 2025–26 financial statements and directors' report.$$,
  $$This is a public-finance and CPSE-governance item. Asset monetisation seeks productive use or value realisation from surplus assets; it does not mean that every government asset is sold or that a recommendation is already a completed transaction.$$,
  $$NLMC is a wholly owned Government of India company under the Department of Public Enterprises in the Ministry of Finance. Its role is to work with CPSEs and other government entities to identify assets, undertake due diligence and valuation, and facilitate appropriate monetisation processes.$$,
  $$NLMC’s 21st Board Meeting Reviews Progress of Monetisation Programme$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2312325&lang=1&reg=3$$,
  $$Ministry of Finance / Press Information Bureau$$, $$2026-09-19$$,
  $$["NLMC recommended monetisation proposals involving assets valued at over ₹5,000 crore.","NLMC is wholly owned by the Government of India and is under the Department of Public Enterprises, Ministry of Finance.","It deals with surplus land and building assets of CPSEs and other government entities.","Identification, due diligence, valuation and process structuring precede an actual monetisation transaction."]$$::jsonb,
  $$[{"question":"Which ministry's department administratively controls NLMC?","answer":"The Department of Public Enterprises under the Ministry of Finance."},{"question":"Is a board recommendation the same as a completed sale?","answer":"No. It is a step before any completed monetisation process."}]$$::jsonb,
  $${"title":"NLMC’s asset-monetisation role","steps":["Asset-owning public entities identify surplus land or buildings.","NLMC supports due diligence and valuation.","The appropriate monetisation process is structured transparently.","A completed transaction can then unlock value from underused assets."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-20-ddugky-2-rollout$$, $$2026-09-20$$,
  $$DDU-GKY 2.0 prepares October skill-training rollout across States and UTs$$,
  $$The Ministry of Rural Development reviewed preparedness for Deen Dayal Upadhyaya-Grameen Kaushalya Yojana (DDU-GKY) 2.0. It said 1,164 batches for 34,920 rural youth are scheduled to begin in October across 14 States and UTs in the first phase.$$,
  $$This tests rural skilling and cooperative implementation. The release concerns a placement-linked, centrally sponsored scheme for poor rural youth; it is an implementation-preparedness update, so the October batches should not be presented as already completed training.$$,
  $$DDU-GKY training lasts from three to twelve months. The Ministry says all 31 participating States and UTs have two-year 2026–28 targets, while the integrated portal is intended to manage the project life cycle, monitoring and, where integrated, online payments through state treasuries.$$,
  $$Ministry of Rural Development to Commence DDU-GKY 2.0 Training Batches Across Most States/UTs from October 2026$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2312317&lang=1&reg=3$$,
  $$Ministry of Rural Development / Press Information Bureau$$, $$2026-09-19$$,
  $$["DDU-GKY is a centrally sponsored, placement-linked skill-training scheme for poor rural youth.","The first-phase October plan covers 1,164 batches and 34,920 rural youth across 14 States and UTs.","Training duration under DDU-GKY ranges from three to twelve months.","All 31 participating States and UTs have DDU-GKY 2.0 targets for the 2026–28 period."]$$::jsonb,
  $$[{"question":"What is DDU-GKY's core training linkage?","answer":"It provides placement-linked skill training for poor rural youth."},{"question":"Were the October 2026 batches already completed on 19 September?","answer":"No. The release describes preparation for their commencement."}]$$::jsonb,
  $${"title":"DDU-GKY 2.0 implementation chain","steps":["The Centre sets scheme targets with participating States and UTs.","States allocate targets to Project Implementing Agencies.","Eligible rural youth are mobilised into training batches.","The integrated portal supports monitoring and project-life-cycle administration."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-20-ngt-mobile-app$$, $$2026-09-20$$,
  $$National Green Tribunal mobile application is launched at environmental-governance conference$$,
  $$The National Green Tribunal (NGT) mobile application was launched during an international conference on the future of environment and climate dynamics in New Delhi. The conference included representatives from 17 countries, UNEP and the Asian Development Bank.$$,
  $$The factual exam link is the institution: NGT is the specialised environmental tribunal. The app launch is a digital-access development; do not confuse it with a new statute, a court judgment or a change to the Tribunal's jurisdiction.$$,
  $$The official account records conference sessions on climate justice and on environmental law and governance. It also recalls central environmental-law principles that recur in Indian jurisprudence, including precaution, polluter pays, absolute liability and the public-trust doctrine.$$,
  $$Prime Minister inaugurates International Conference on the Future of Environment and Climate Dynamics; Releases NGT Mobile Application$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2312360&lang=2&reg=48$$,
  $$Ministry of Environment, Forest and Climate Change / Press Information Bureau$$, $$2026-09-19$$,
  $$["The NGT mobile application was launched during the international environment and climate conference in New Delhi.","NGT is a specialised environmental tribunal, not a ministry or a constitutional court.","The conference involved delegates from 17 countries as well as UNEP and ADB.","The source discusses the precautionary principle, polluter-pays principle, absolute liability and public-trust doctrine in environmental jurisprudence."]$$::jsonb,
  $$[{"question":"Which institution's mobile application was launched?","answer":"The National Green Tribunal's."},{"question":"Is the NGT a ministry?","answer":"No. It is a specialised environmental tribunal."}]$$::jsonb,
  $${"title":"Digital access and environmental adjudication","steps":["Environmental disputes and compliance issues require specialised institutions.","The NGT is the central specialised tribunal in this framework.","A mobile application expands a digital service channel.","Underlying environmental principles remain legal and institutional reference points."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-20-sugar-stockholding-relaxation$$, $$2026-09-20$$,
  $$Government relaxes bulk-consumer sugar stockholding limit to 30 days$$,
  $$The government relaxed the sugar stockholding limit for bulk consumers from 15 to 30 days. Stock held above the existing 15-day limit must be sourced only from sugar imported under the Advance Authorization Scheme or the Tariff Rate Quota, while open-market purchases remain capped at 15 days' consumption.$$,
  $$This is a food-management and trade-policy distinction. The relaxation is conditional: it neither removes the open-market cap nor applies without regard to the source of the additional sugar.$$,
  $$Bulk consumers using more than 10 metric tonnes of sugar per month as raw material are covered by the policy described in the release. The government also requires weekly stock declaration and disclosure through the Department of Food and Public Distribution's portal.$$,
  $$Government Relaxes Sugar Stockholding Limit for Bulk Consumers from 15 to 30 Days$$,
  $$https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2311960&lang=2&reg=48$$,
  $$Ministry of Consumer Affairs, Food and Public Distribution / Press Information Bureau$$, $$2026-09-18$$,
  $$["The bulk-consumer sugar stockholding limit was relaxed from 15 to 30 days.","Additional stock beyond 15 days must come exclusively through Advance Authorization Scheme or Tariff Rate Quota imports.","Open-market purchase remains limited to 15 days' consumption.","The policy described applies to bulk consumers using more than 10 MT of sugar per month and requires weekly stock disclosure."]$$::jsonb,
  $$[{"question":"What is the ordinary open-market sugar-stock limit after this change?","answer":"15 days' consumption."},{"question":"What condition applies to the additional stock up to 30 days?","answer":"It must be sourced from sugar imported under AAS or TRQ."}]$$::jsonb,
  $${"title":"Conditional sugar-stock relaxation","steps":["Bulk consumers face an ordinary 15-day holding rule.","Government permits holding up to 30 days.","The extra quantity must come from specified import channels.","Weekly disclosure supports monitoring of the stock position."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-20-semicon-2-ecosystem$$, $$2026-09-20$$,
  $$Semicon 2.0 targets a full domestic semiconductor ecosystem$$,
  $$At SEMICON India 2026, the government outlined Semicon 2.0 as the next phase of the India Semiconductor Mission. It expands the focus beyond foundation building to six pillars: design, equipment and materials, fabs, advanced packaging, applied research and development, and talent.$$,
  $$This is a technology-industrial-policy item. Semicon 2.0 is an ecosystem roadmap, not a claim that every approved fabrication unit is operating. The release distinguishes production lines that are live from projects still progressing through development and approvals.$$,
  $$The official release says Semicon 1.0 trained 70,000 design engineers and deployed electronic design automation tools at more than 500 organisations. The government states that the mission budget is to rise from USD 8 billion under Semicon 1.0 to USD 13.5 billion under Semicon 2.0.$$,
  $$Prime Minister inaugurates SEMICON India 2026 and unveils roadmap for transition to Semicon 2.0$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2311726&lang=1&reg=3$$,
  $$Ministry of Electronics and Information Technology / Press Information Bureau$$, $$2026-09-17$$,
  $$["Semicon 2.0 has six pillars: design; equipment and materials; fabs; advanced packaging; applied R&D; and talent.","It follows the foundation-building phase referred to as Semicon 1.0.","The release says Semicon 1.0 trained 70,000 design engineers and deployed EDA tools at 500-plus organisations.","The announced mission budget moves from USD 8 billion under Semicon 1.0 to USD 13.5 billion under Semicon 2.0."]$$::jsonb,
  $$[{"question":"Name any two Semicon 2.0 pillars.","answer":"For example, design and advanced packaging."},{"question":"Does a roadmap mean all fabrication projects are already operational?","answer":"No. It sets the direction; project stages differ."}]$$::jsonb,
  $${"title":"Semicon 2.0 value-chain approach","steps":["Chip design requires people, tools and intellectual property.","Fabs need materials, equipment and reliable supply chains.","Packaging, R&D and talent turn individual projects into an ecosystem.","Mission support aims to expand domestic capability across the value chain."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-20-onetag-fastag-portability$$, $$2026-09-20$$,
  $$OneTag lets FASTag users change issuer without replacing the physical tag$$,
  $$NHAI's Rajmargyatra app now hosts OneTag, a FASTag portability service. An eligible user can switch issuer banks while retaining the same FASTag affixed to the vehicle and the same FASTag ID linked to the vehicle-registration number.$$,
  $$This is a digital-payments and transport-infrastructure item. It tests the distinction between the physical tag, its issuer and its wallet—portability shifts the issuer but does not preserve the old wallet balance with the previous issuer.$$,
  $$The app guides verification with a six-digit Mobile Verification Code from the current issuer, then selection and onboarding with the new issuer. The previous issuer closes the old wallet and refunds its available balance after adjustments. The interoperable FASTag has a six-month cooling period before it can be ported again.$$,
  $$NHAI Rajmargyatra App Hosts OneTag FASTag Portability Service$$,
  $$https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2311392&lang=2&reg=48$$,
  $$Ministry of Road Transport and Highways / Press Information Bureau$$, $$2026-09-17$$,
  $$["OneTag enables an eligible FASTag user to change issuer while retaining the existing physical tag.","The FASTag ID linked to the vehicle registration number remains unchanged after successful portability.","The former issuer closes the old wallet and refunds its available balance after applicable adjustments.","A six-month cooling period applies before another portability request for an interoperable FASTag."]$$::jsonb,
  $$[{"question":"What remains unchanged after OneTag portability?","answer":"The existing physical tag and its FASTag ID linked to the vehicle."},{"question":"Can a FASTag be ported again immediately?","answer":"No. The release sets a six-month cooling period."}]$$::jsonb,
  $${"title":"How OneTag portability works","steps":["The user checks eligibility in Rajmargyatra.","The current issuer verifies the request.","The user completes onboarding with a new issuer.","The tag stays on the vehicle while the old wallet is closed and settled."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-20-ulb-waste-ghg-tool$$, $$2026-09-20$$,
  $$PSA launches GHG calculator and life-cycle framework for urban waste management$$,
  $$The Office of the Principal Scientific Adviser launched a digital greenhouse-gas calculator and released a life-cycle-assessment framework for Indian solid-waste-management technologies. The project was undertaken by IISc Bengaluru, IIT Madras and IIT (BHU) with PSA support.$$,
  $$This is a science-to-governance tool for Urban Local Bodies. It supports decisions among waste-management pathways; it is not itself a waste-processing mandate or a substitute for an individual city's regulatory approvals.$$,
  $$The tool can analyse existing solid-waste practices and compare alternatives such as anaerobic digestion, incineration or waste-to-energy, composting, recycling and landfilling. It reports net, avoided and logistics emissions and several greenhouse-gas indicators to help ULBs identify lower-carbon scenarios.$$,
  $$Principal Scientific Adviser launches digital platform to optimise waste management in cities$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2311186&lang=1&reg=3$$,
  $$Office of the Principal Scientific Adviser to the Government of India / Press Information Bureau$$, $$2026-09-17$$,
  $$["The project produced an India-specific life-cycle-assessment framework and a GHG calculator for solid waste management.","It was undertaken by IISc Bengaluru, IIT Madras and IIT (BHU) with Office of PSA support.","The calculator is designed for Urban Local Bodies and compares emissions across waste-management scenarios.","The listed pathways include anaerobic digestion, waste-to-energy or incineration, composting, recycling and landfilling."]$$::jsonb,
  $$[{"question":"Which local institution is the primary intended user of the calculator?","answer":"Urban Local Bodies."},{"question":"Is life-cycle assessment limited to landfill emissions?","answer":"No. It can compare multiple technologies and operating scenarios."}]$$::jsonb,
  $${"title":"Using LCA for municipal waste choices","steps":["A ULB enters its waste-management conditions.","The calculator estimates emissions for current and alternative pathways.","Life-cycle comparison identifies trade-offs and lower-carbon scenarios.","Results can inform project reports, tenders and municipal planning."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-20-net-zero-napcc-dashboards$$, $$2026-09-20$$,
  $$India launches Net Zero Portal and NAPCC Dashboard for climate-action tracking$$,
  $$The Ministry of Environment, Forest and Climate Change launched two digital platforms: the Net Zero Portal for voluntary entity-level net-zero commitments and the NAPCC Dashboard for consolidated monitoring of National Action Plan on Climate Change missions.$$,
  $$The key distinction is voluntary disclosure versus government monitoring. The Net Zero Portal is not a mandatory national carbon-accounting registry, while the NAPCC Dashboard tracks mission information and indicators across ministries and departments.$$,
  $$On the Net Zero Portal, participating entities can disclose greenhouse-gas emissions, targets and annual progress. Scope 1 and Scope 2 reporting is encouraged; Scope 3 reporting remains voluntary. The NAPCC Dashboard is intended to support inter-ministerial coordination, assessment of gaps and links between domestic climate action and international commitments.$$,
  $$Union Minister launches India’s Net Zero Portal and NAPCC Dashboard on World Ozone Day 2026$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2310737&lang=2&reg=48$$,
  $$Ministry of Environment, Forest and Climate Change / Press Information Bureau$$, $$2026-09-16$$,
  $$["The Net Zero Portal records voluntary net-zero commitments and related disclosures by participating Indian entities.","The NAPCC Dashboard provides a consolidated monitoring view across National Action Plan on Climate Change missions.","The Portal encourages Scope 1 and Scope 2 emissions reporting, while Scope 3 reporting remains voluntary.","The two platforms were launched by the Ministry of Environment, Forest and Climate Change on World Ozone Day 2026."]$$::jsonb,
  $$[{"question":"Which platform is for voluntary entity-level net-zero declarations?","answer":"India's Net Zero Portal."},{"question":"Is Scope 3 disclosure mandatory on the new Portal?","answer":"No. The release says it remains voluntary."}]$$::jsonb,
  $${"title":"Two climate-data platforms, two functions","steps":["Entities disclose voluntary net-zero commitments on the Net Zero Portal.","Their emissions, targets and progress can be recorded transparently.","The NAPCC Dashboard consolidates mission-level government information.","Together they support public disclosure and inter-ministerial monitoring."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-20-trade-watch-quarterly-q1-fy27$$, $$2026-09-20$$,
  $$NITI Aayog’s Trade Watch Quarterly focuses on India’s metals and ores trade$$,
  $$NITI Aayog released the ninth Trade Watch Quarterly for the first quarter of FY 2026–27, covering April to June 2026. The edition analyses global and domestic trade trends and has a thematic focus on India's metals and ores trade.$$,
  $$This is a report-and-data item rather than an announcement of new trade rules. It is useful for trade-policy questions on critical minerals, value addition and the Carbon Border Adjustment Mechanism, but its figures should be cited as the report's assessment for its stated period.$$,
  $$The report says India's total merchandise and services trade in Q1 FY27 reached USD 506.9 billion, a year-on-year rise of 15.5%. It examines export competitiveness and import dependence in metals and ores, including critical minerals and higher-value non-ferrous metals, and relates them to manufacturing, infrastructure and energy transition.$$,
  $$NITI Aayog Launches Ninth Edition of Trade Watch Quarterly$$,
  $$https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2310941&lang=2&reg=48$$,
  $$NITI Aayog / Press Information Bureau$$, $$2026-09-16$$,
  $$["The ninth Trade Watch Quarterly covers Q1 FY 2026–27, or April–June 2026.","Its thematic focus is India's metals and ores trade.","The report estimates India's total merchandise and services trade at USD 506.9 billion in Q1 FY27, up 15.5% year on year.","It links critical minerals and higher-value non-ferrous metals with domestic value addition, import dependence and competitiveness."]$$::jsonb,
  $$[{"question":"What period does this Trade Watch Quarterly cover?","answer":"Q1 of FY 2026–27: April to June 2026."},{"question":"What sector is the edition's thematic focus?","answer":"India's metals and ores trade."}]$$::jsonb,
  $${"title":"Trade Watch Quarterly analytical frame","steps":["The report sets global and domestic trade context.","It studies a strategically important sector: metals and ores.","Trade patterns reveal opportunities and import dependencies.","Findings inform policy on value addition, resources and export competitiveness."]}$$::jsonb,
  $$published$$, now()
)
on conflict (slug) do update set
